Terraform v1.17.1
on linux_amd64

resource "terraform_data" "owned" {
  input = {
    team = var.team
    name = var.name
  }
}
output "team" {
  description = "Team that owns the resource."
  value       = var.team
}
variable "team" {
  description = "Team that owns the resource."
  type        = string
}

variable "name" {
  description = "Name of the resource."
  type        = string
}
terraform {
  required_version = ">= 1.3.0"
}

